        heading: '環境モデル都市と再生可能エネルギー',
        body: `公害を経験した都市は、その反省を出発点にして環境先進都市へと変わってきた。

■ 水俣市の取り組み
水俣市は市民・企業・行政が協力して環境の再生に取り組み、環境モデル都市に選ばれた。家庭ごみを20種類以上に分別する取り組みは全国的に有名で、ごみの減量とリサイクル率の向上につながっている。海の水銀を含む泥は埋め立てて封じこめられ、現在の水俣湾でとれる魚は安全が確認されている。水俣病資料館では、二度と同じことをくり返さないための語り部の活動が続けられている。

■ 北九州市のエコタウン
かつて「死の海」と呼ばれた洞海湾を再生させた北九州市は、エコタウン事業として使用済みの家電・自動車・ペットボトルなどをリサイクルする企業を集めている。ごみを別の産業の原料として使い、地域全体でむだを減らすしくみである。

■ 3Rと循環型社会
・リデュース（Reduce）…そもそもごみを出さない、使う資源を減らす。
・リユース（Reuse）…洗ってくり返し使う、修理して使う。
・リサイクル（Recycle）…原料にもどして作り直す。
この順に優先するのが原則で、リサイクルは最後の手段である点に注意する。リサイクルにもエネルギーが必要だからである。

■ 九州の再生可能エネルギー
大分県の八丁原発電所に代表される地熱発電、日照時間の長さをいかした太陽光発電、家畜のふん尿や木くずを利用するバイオマス発電など、九州は再生可能エネルギーの導入が進んでいる。ただし太陽光や風力は天候によって発電量が変わるため、電力があまる時間帯には発電を止めてもらう出力制御が行われることもある。安定して電気を送るしくみづくりが今後の課題である。

⚠ 注意：3Rの順番を「リサイクル→リユース→リデュース」と逆に覚えると、記述問題で減点される。「まず減らす」が出発点である。`,
