        heading: 'コンビナートと地域ごとの特色',
        body: `■ 石油化学コンビナートのしくみ
コンビナートとは、関連する工場をパイプラインでつなぎ、一つの工場から出た製品や副産物を次の工場の原料として使う工場の集まりである。
例）タンカーで運ばれた原油 → 石油精製工場でガソリン・灯油・ナフサなどに分ける → ナフサを石油化学工場に送る → プラスチックや合成ゴム、化学繊維の原料をつくる。
パイプでつながっているので、輸送費と時間を大きくおさえられる。この結果、瀬戸内工業地域は化学工業の割合が全国の工業地域の中でも高くなっている。

■ おもな都市と工業
・倉敷市水島…石油化学と鉄鋼が並ぶ日本有数の臨海工業地区。
・周南市・岩国市（山口県）…石油化学。
・新居浜市（愛媛県）…別子銅山の製錬から発展した化学・非鉄金属。
・広島市…自動車工業。関連する部品工場が周辺に集まる。
・呉市・坂出市・今治市…造船。日本の造船の中心地の一つ。
・今治市…タオルの生産で全国の大部分を占める地場産業。
・備前市・府中市など…耐火れんが、家具といった伝統的な地場産業。

■ 環境の課題
瀬戸内海は外海とつながる海峡が狭く、水が入れかわりにくい閉鎖性水域である。高度経済成長期には工場排水や生活排水で汚れ、プランクトンが異常に増える赤潮がたびたび発生して養殖の魚に大きな被害を出した。1973年に瀬戸内海環境保全臨時措置法が定められ、排水の規制が進められた結果、水質は改善してきた。近年は逆に、栄養が減りすぎてのりの色が悪くなるという新しい問題も指摘されている。

⚠ 注意：瀬戸内工業地域は「機械工業がゼロ」ではない。全国の工業地域と比べたときに化学の割合が相対的に高い、という読み取り方をする。`,
