みかんが斜面に向くのには理由がある。
①日当たりがよい…南向きの斜面は光をよく受ける。海面からの反射光も加わる。
②水はけがよい…斜面なので水がたまらない。みかんは根が水につかることをきらう。
③昼と夜の温度差…実がよく色づき、甘みが増す。
一方で、機械が入りにくく作業がきついため、モノレール（傾斜地用の運搬機）を設置するなどの工夫がされている。みかんの主産地は和歌山県・愛媛県・静岡県で、いずれも温暖で水はけのよい傾斜地をもつ。
なお、みかんは輸入オレンジの自由化（1991年）以降きびしい競争にさらされ、他の柑橘（伊予柑、デコポンなど）への転換や、ブランド化が進められた。

