        heading: '三つに分かれる近畿の地形と気候',
        body: `近畿地方は南北に長く、北から順に大きく三つの地域に分けられる。

■ 北部（日本海側）
丹波高地や若狭湾に面した地域で、冬に北西季節風の影響を受け、雪や雨が多い。若狭湾は山地が沈んでできたリアス海岸で、入り江が複雑に入り組んでいる。波が静かなため、漁港や原子力発電所の立地に利用されてきた。

■ 中央部（低地）
琵琶湖・京都盆地・奈良盆地・大阪平野が並ぶ。周囲を山に囲まれた盆地では、夏は蒸し暑く冬は冷えこむ内陸性の気候となり、京都の夏の暑さ・冬の底冷えはよく知られている。大阪平野は淀川と大和川が運んだ土砂でできた平野で、日本第二の大都市圏がここに広がっている。

■ 南部（太平洋側）
紀伊山地がそびえ、夏の南東季節風と台風の影響で降水量が非常に多い。三重県の尾鷲は年降水量が約4,000mmに達し、日本有数の多雨地域である。豊富な雨は木をよく育てるため、林業がさかんになった。太平洋に突き出た志摩半島や、和歌山県の海岸線にもリアス海岸がみられる。

★ ポイント：同じ近畿でも「北＝冬に雪、中央＝内陸性、南＝多雨」と、気候が三つに分かれることを地図とセットで覚える。`,
