        heading: '碁盤の目の都市と文化財',
        body: `奈良の平城京、京都の平安京は、いずれも中国の都にならって計画的につくられた都である。東西・南北に道路を直角に交わらせる条坊制が採用されたため、現在の京都の中心部も道路が碁盤の目のように走っている。京都で「烏丸通と四条通の交差点」と言えば場所が特定できるのは、この規則的な道路網のおかげである。

■ 文化財の集積
京都には清水寺・金閣（鹿苑寺）・二条城など、奈良には東大寺・法隆寺・興福寺などが残る。「古都京都の文化財」「古都奈良の文化財」「法隆寺地域の仏教建造物」はいずれも世界文化遺産に登録されている。
これらの寺社は木造建築が多いため、火災に弱い。放水銃や防火水槽が境内に設けられ、文化財防火デーには消防訓練が行われている。

■ 古都保存法
1960年代、京都や鎌倉の周辺の丘陵で宅地開発が進み、寺社の背景となる山なみが失われそうになった。そこで1966年に古都保存法が定められ、指定された地域では建物の新築や樹木の伐採に許可が必要になった。「建物そのものだけでなく、その周囲の風景（歴史的風土）ごと守る」という考え方が特徴である。

★ ポイント：文化財保護は「点（建物）→面（町並み）→背景（山なみ）」と守る範囲が広がってきた、という流れで理解する。`,
