        body: `紀伊山地は年降水量が非常に多く、木がまっすぐ早く育つ。この条件をいかして、室町時代ごろから計画的な植林が行われてきた。人が植えて育てた森林を人工林という。

■ 代表的な産地
・吉野すぎ（奈良県）…苗を非常に密に植え、少しずつ間引くことで、年輪がつまった木目の美しい材を育てる。酒だるの材として重用されてきた。
・尾鷲ひのき（三重県）…多雨とやせた土でゆっくり育つため、木目が細かくねばりが強い。
これらは静岡県の天竜すぎとあわせて、日本を代表する人工の美林とされる。

■ 林業のサイクル
①植林（苗を植える）→②下刈り（雑草を刈る）→③枝打ち（下枝を落とし、節のない材にする）→④間伐（混みすぎた木を間引き、残る木に光を当てる）→⑤主伐（伐り出す）。
植えてから伐り出すまで、すぎで40〜50年、ひのきでは60年以上かかる。植えた人が収穫するのではなく、次の世代が受け取るという長い時間の産業である。

■ 衰退の理由
①1960年代の木材輸入の自由化以降、安い外国産の木材が大量に入り、国産材の価格が下がった。
②価格が下がったため、手間のかかる手入れをしても採算が合わなくなった。
③山村の若者が都市へ出て、働き手が高齢化・不足した。
④住宅が木造以外の工法に変わり、国内の木材需要そのものが減った時期があった。
その結果、木材自給率は1960年代の9割前後から2000年ごろには2割程度まで落ちこんだ。近年は国産材の利用が見直され、4割前後まで回復してきている。

★ ポイント：林業の問題は「安い輸入材」「長い育成期間」「担い手不足」の三つで説明する。`,
