        body: `北陸の冬は、単に寒いのではなく「雪が多い」ことが最大の特徴である。積雪が2mをこえる地域もある。

■ なぜこれほど雪が降るのか
①シベリアから吹き出す冷たく乾いた北西季節風が、
②暖流（対馬海流）が流れる日本海の上を渡るあいだに大量の水蒸気を受け取り、
③本州の山地にぶつかって上昇し、冷やされて雪となる。
日本海という「水蒸気の供給源」があることが、世界的にも珍しい多雪の理由である。同じ緯度の大陸の内陸部では、これほどの雪は降らない。

■ 雪への備え
・雁木（がんぎ）…道に面した家の軒を長く張り出し、雪の日でも通れる歩道をつくる伝統的な工夫。新潟県の商店街に残る。
・消雪パイプ…道路の中央から地下水をまいて雪をとかす。北陸の市街地で広く使われる。
・落雪式の屋根、高床の玄関、除雪機。
・雪を夏まで保存して冷房や農産物の貯蔵に使う「雪室（ゆきむろ）」の利用も広がっている。

■ 雪がもたらすめぐみ
①豊富な雪どけ水…春の田植えの時期にちょうど水が得られ、稲作を支える。
②水力発電…急な川と豊富な水量をいかして発電し、その電力を利用してアルミニウム精錬などの電気を大量に使う工業が発達した（富山県など）。
③冬の農閑期の副業…雪で農作業ができない冬に室内でできる手仕事が発達し、それが地場産業（後の単元で扱う）につながった。

⚠ 注意：日本海側で雪が多い理由に「日本海の上で水蒸気を含む」という段階を書き忘れると、説明が不十分になる。季節風・日本海・山地の三つをそろえる。`,
