        body: `■ 高原野菜（高冷地農業）
八ヶ岳の山ろくに広がる野辺山原（長野県南牧村など）や、菅平高原では、標高1,000〜1,400mの涼しい気候をいかしてレタス・キャベツ・はくさいが栽培されている。

なぜここで作るのか。レタスやはくさいは涼しい気候を好み、暑さに弱い。平地では夏に作れない。ところが高原は夏でも涼しいので、平地の産地が出荷できない6月から9月に出荷できる。市場に品物が少ない時期なので、価格が高くなる。
このように、出荷の時期を遅らせる（＝他産地とずらす）栽培を抑制栽培という。促成栽培（早める）と対になる用語である。

■ 発達を支えた条件
①高速道路（中央自動車道など）の開通で、朝収穫した野菜をその日のうちに東京・名古屋の市場へ運べるようになった。
②保冷トラック（コールドチェーン）の発達で鮮度を保てるようになった。
③戦後、開拓によって農地が広げられた。
かつては養蚕のための桑畑だった土地が、化学繊維の普及で生糸の需要が減ったあと、野菜畑に転換された経緯もある。

■ 甲府盆地の果樹
山梨県の甲府盆地には、川が山地から出たところに土砂が積もってできた扇状地が広がる。扇状地は粒の大きな石や砂でできているため水がしみこみやすく、水田には向かないが、水はけを好むぶどう・ももには最適である。山梨県はぶどうとももの収穫量がいずれも全国第1位で、ワインの生産もさかんである。近年は観光農園（ぶどう狩り・もも狩り）として都市住民を呼びこむ取り組みも広がっている。

★ ポイント：「扇状地＝水はけがよい＝果樹」「三角州＝水もちがよい＝水田」の対比は、地形と土地利用の定番の組み合わせである。`,
