        body: `中央高地の工業は、原料と技術を受けつぎながら姿を変えてきた。

■ ①製糸業の時代（明治〜昭和初期）
桑を育ててかいこを飼い、まゆから生糸をつくる養蚕・製糸業がさかんだった。とくに諏訪・岡谷は「日本一の生糸の町」といわれ、生糸は当時の日本最大の輸出品だった。

■ ②精密機械工業への転換（戦中〜戦後）
第二次世界大戦中、空襲を避けるために都市部の工場が疎開してきた。加えて、次の条件が精密機械に適していた。
・きれいな空気と水…ほこりをきらう精密部品の製造に向く。
・製糸業でつちかわれた、細かい作業に慣れた働き手がいた。
こうして諏訪地方は時計・カメラ・オルゴールなどの精密機械の産地となり、「東洋のスイス」と呼ばれた。

■ ③電子部品・情報機器へ（1980年代以降）
時計やカメラが電子化・海外生産へ移るなか、精密加工の技術をいかして電子部品、プリンターなどの情報関連機器へ転換が進んだ。中央自動車道や長野自動車道の開通により、高速道路のインターチェンジ付近に工場が建てられた。IC工場が高速道路沿いに並ぶ様子から、中央自動車道沿いは「シリコンロード」と呼ばれることもある。

■ 観光業
上高地・志賀高原・軽井沢などは避暑地・スキー場としてにぎわい、観光は中央高地の重要な産業である。近年は外国人スキー客の増加もみられる一方、暖冬による積雪不足という気候変動の影響も心配されている。

⚠ 注意：精密機械が中央高地で発達した理由に「原料が近くでとれるから」と書くのは誤り。精密機械は原料の重さより、きれいな水と空気、技術をもつ人が重要である。`,
