        heading: '水田単作地帯としての北陸',
        body: `北陸は日本有数の米どころである。新潟県の米の収穫量は全国第1位で、富山県・石川県・福井県も上位に入る。

■ なぜ稲作が中心なのか
①春の豊富な雪どけ水…田植えの時期に水が確実に得られる。
②広い平野…越後平野・富山平野・砺波平野・福井平野など、川がつくった平野が広がる。
③夏の高温と長い日照…日本海側は夏に晴天が多く、稲が実る時期の気温が高い。フェーン現象で気温が上がることもある。

■ 水田単作とは
北陸では、冬は雪におおわれて畑作ができない。そのため一年に稲だけをつくる水田単作が一般的である。これに対し、冬でも温暖な筑紫平野では、夏に米、冬に麦をつくる二毛作が行われる。「北陸＝水田単作」「九州北部＝二毛作」と対で覚える。

■ 低湿地から美田へ
越後平野はもともと排水の悪い低湿地で、腰までつかりながら農作業をするような土地だった。大河津分水（信濃川の水を日本海へ直接流す放水路）の完成や、排水機場・暗きょ排水の整備によって水はけがよくなり、日本有数の水田地帯に生まれ変わった。土地改良で区画を大きくし、機械が入れるようにする整備も進められた。

■ 銘柄米とこれから
コシヒカリに代表される銘柄米は、味のよさで高い価格を保ってきた。近年は各県が新しい品種（新潟の新之助、富山の富富富など）を開発して競い合っている。一方、日本人の米の消費量は減り続けているため、米の輸出や、米粉の利用、飼料用米への転換など、新しい使い道を探る動きがある。

★ ポイント：北陸の稲作の答案には「雪どけ水」「広い平野」「冬は雪で他の作物が作れない」の三点を入れる。`,
