        heading: '一極集中の理由と問題',
        body: `■ なぜ東京に集まるのか
①政治の中心…国会議事堂、内閣、中央省庁、最高裁判所が集まる首都である。
②経済の中心…大企業の本社が集中し、金融・保険の中心でもある。省庁や取引先が近いことが本社を置く利点になる。
③情報の中心…新聞社・テレビ局・出版社が集まり、最新の情報が集まりやすい。
④教育・文化…大学、専門学校、劇場、美術館が集中し、進学のために若者が集まる。
⑤交通の結節点…新幹線・高速道路・空港が集まり、全国どこへも移動しやすい。
これらは互いに引き合う。企業があるから人が集まり、人が集まるから企業が来る、という循環が集中を強めてきた。

■ 起きている問題
・通勤ラッシュ…長い通勤時間と混雑が生活の質を下げる。
・地価と家賃の高騰…住宅を都心近くに確保しにくい。
・待機児童…保育所が足りない地域が生じる。
・災害時の帰宅困難者…大地震で鉄道が止まると、数百万人が帰宅できなくなると想定されている。むやみに移動せず職場や学校にとどまる「一斉帰宅の抑制」が呼びかけられている。
・地方の人口減少…東京へ人が移ることで、地方では過疎と高齢化が進む。とくに若い世代の流出は、その地域の将来の出生数を減らす。

■ 対策
・中央省庁や独立行政法人の地方移転（文化庁の京都移転など）。
・企業の地方拠点づくりへの税の優遇。
・テレワーク・リモートワークの普及…住む場所と働く場所を切り離す。都市から地方へ移住する動きも一部でみられた。
・二地域居住…平日は都市、週末は地方といった暮らし方。
・地方創生…自治体が仕事づくり・子育て支援・移住支援に取り組む。

⚠ 注意：「一極集中」は東京だけの問題ではなく、地方の人口減少と表裏一体である。片方だけを書くと、記述問題としては不十分になりやすい。`,
