        body: `大都市の周辺で、都市に住む人々に向けて野菜・花・鶏卵・生乳などを生産する農業を近郊農業という。関東地方では、茨城県・千葉県・埼玉県・神奈川県などで発達している。

■ なぜ大都市の近くなのか
①輸送費が安い…距離が短いほど運ぶ費用が少なくてすむ。
②鮮度を保てる…ほうれんそう・こまつな・レタスなどの葉物野菜は、いたみやすく重量あたりの価格が高くないため、遠くから運ぶと採算が合わない。
③需要が大きく安定している…人口が多いので、毎日大量に売れる。
④消費地の情報が届きやすい…どんな品種が売れるかを早くつかめる。

■ 何を作っているか
・茨城県…はくさい、ピーマン、れんこん、メロン。野菜の産出額は全国上位。
・千葉県…だいこん、ねぎ、ほうれんそう、落花生（全国生産の大部分）。
・埼玉県…ねぎ、ほうれんそう。
・神奈川県…だいこん、キャベツ、花き。
・群馬県…キャベツ（嬬恋村）、こんにゃくいも（全国生産のほとんど）。
関東ロームの台地は水はけがよく、野菜づくりに向いていることも背景にある。

■ 近郊農業と輸送園芸
近郊農業に対して、遠く離れた産地が輸送手段を発達させて大都市へ出荷する農業を輸送園芸（遠郊農業）という。宮崎県や高知県の促成栽培、長野県の抑制栽培がこれにあたる。
・近郊農業…「近さ」を武器に、鮮度と輸送費で勝負する。
・輸送園芸…「時期のずれ」を武器に、他産地の少ない時期に高く売る。
この二つは競合するのではなく、季節ごとに市場を分け合っている。年間を通じて野菜が並ぶのは、この分業のおかげである。

★ ポイント：「なぜこの県で作るのか」を問われたら、近い産地なら「鮮度・輸送費」、遠い産地なら「時期をずらす」と答え方を切りかえる。`,
