        heading: 'やませと冷害',
        body: `東北地方の中央には奥羽山脈が南北に走り、地方を太平洋側と日本海側に分けている。この山脈が気候の境になっている。

■ やませとは
夏、オホーツク海のあたりで発達した高気圧から、冷たく湿った北東の風が東北の太平洋側に吹きこむことがある。この風をやませという。
やませが吹くと、
①気温が上がらない（低温）。
②霧や雲が広がり、日照が不足する。
この二つが重なると、稲は十分に育たず、実らないまま秋を迎える。これが冷害である。
1993年には全国的な大冷害が起き、東北の一部では米がほとんどとれず、日本は外国から米を緊急輸入することになった。

■ なぜ太平洋側だけなのか
やませは奥羽山脈にさえぎられるため、日本海側にはほとんど届かない。むしろ山を越えるときに雨を落とし、日本海側では乾いた高温の風になる（フェーン現象）。同じ東北でも、太平洋側は冷害、日本海側は高温という正反対のことが同時に起こりうる。

■ 冷害への対策
・冷害に強い品種の開発（耐冷性品種）。
・田の水を深く張って、水の熱で稲を保護する深水管理。
・育苗の時期を調整し、危険な時期に穂が出ないようにする。
・気象データを使った生育予測と、農家への早期の情報提供。
これらによって、かつてほどの大凶作は起こりにくくなった。

★ ポイント：やませの答案は「北東の風」「冷たく湿っている」「低温と日照不足」「太平洋側」の四点をそろえる。`,
