        heading: '三陸海岸と潮目',
        body: `■ リアス海岸
三陸海岸の南部（岩手県南部から宮城県北部）は、複雑に入り組んだリアス海岸である。
成り立ちは、山地が沈降する（または海面が上昇する）ことで、谷だったところに海水が入りこみ、尾根が岬として残るというものである。
・利点…入り江の奥は波が静かで水深があり、天然の良港になる。養殖のいかだを浮かべるのにも適する。宮城県の気仙沼・女川、岩手県の宮古・釜石などが漁港として発達した。わかめ・かき・ほたて・ぎんざけの養殖がさかんである。
・弱点…津波が湾の奥へ進むにつれて幅が狭まり水深が浅くなるため、波が高く持ち上がる。過去にも明治三陸地震（1896年）、昭和三陸地震（1933年）、東日本大震災（2011年）で大きな被害を受けている。
日本でリアス海岸がみられる場所は、三陸海岸のほか若狭湾、志摩半島、宇和海沿岸などである。

■ 潮目（潮境）
三陸沖は、南から北上する暖流の黒潮（日本海流）と、北から南下する寒流の親潮（千島海流）がぶつかる海域である。この境目を潮目（潮境）という。
・冷たい水と暖かい水が混ざることで海水がかき混ぜられ、海底の栄養分が上がってくる。
・プランクトンが大量に発生し、それを食べる魚が集まる。
そのため三陸沖は世界有数の漁場となり、さんま・さば・いわし・かつおなどがとれる。

■ その他の地形
・北部の三陸海岸…岩手県北部は断崖が続く海岸で、リアス海岸ではない。
・八郎潟（秋田県）…かつて日本第2の湖だったが、戦後に干拓されて大規模な水田になった。大潟村が生まれた。
・十和田湖…火山のカルデラに水がたまってできたカルデラ湖。
・最上川…山形県を流れ、庄内平野をうるおす。

⚠ 注意：三陸海岸すべてがリアス海岸ではない。リアス海岸は南部（宮古以南）であり、北部は隆起した台地が海に落ちる断崖の海岸である。`,
