        heading: '盆地が育てる果樹',
        body: `東北地方は果樹栽培でも全国有数である。栽培の中心は、山に囲まれた盆地と、その中の扇状地である。

■ 盆地・扇状地が果樹に向く理由
①水はけがよい…扇状地は砂や石が積もった地形で、水がたまらない。果樹は根が水につかることをきらう。
②昼夜の気温差が大きい…内陸の盆地は日中と夜間の温度差が大きく、果実に糖分がたまって甘くなる。
③日当たりがよい…傾斜地や扇状地は日照を得やすい。

■ 主な産地
・青森県…りんご。津軽平野（弘前市など）が中心で、全国生産量の約6割を占める。冷涼な気候がりんごに適する。第2位は長野県。
・山形県…さくらんぼ（おうとう）。山形盆地が中心で、全国の約7割を占める。西洋なし（ラ・フランス）も全国第1位。
・福島県…もも。福島盆地が中心で、山梨県に次いで全国第2位。
・岩手県…りんご、雑穀。

■ 産地の工夫
りんごは日光がよく当たるよう葉を摘み、地面に反射シートを敷いて実全体を色づかせる。台風で実が落ちる被害を防ぐため防風網を張る。近年は、蜜が入る品種や、皮ごと食べられる小型の品種の開発、輸出（台湾・香港など）にも力を入れている。
さくらんぼは雨に当たると実が割れるため、雨よけのテントをかける。収穫期が短く、手作業が中心のため、人手の確保が課題である。

★ ポイント：「盆地＋扇状地＋昼夜の気温差」は、山梨県（ぶどう・もも）でも東北でも共通する果樹栽培の条件である。`,
