        heading: '復興と、これからの備え',
        body: `■ 復興のまちづくり
・高台移転…住宅を高い土地へ移し、もとの低地は公園・農地・産業用地として使う。
・かさ上げ…土を盛って土地全体の高さを上げ、その上に街を再建する。
・防潮堤…海岸に高い堤防を築く。ただし「海が見えなくなる」「景観と漁業に影響する」といった議論もあり、高さをめぐって住民の話し合いが重ねられた。
・避難路と津波避難タワー…すぐに高い場所へ逃げられるよう、階段や避難タワーを整備する。
・三陸沿岸道路…被災地を南北に結ぶ道路が整備され、救援と復興、そして日常の移動を支えている。
一方で、人口の流出は続いており、住民が戻らないまま整備された土地が残るという課題もある。

■ 水産業の再生
壊れた漁港・市場・水産加工場が復旧し、わかめ・かき・ほたてなどの養殖も再開された。共同での漁船利用や、加工から販売まで手がける取り組みも進んでいる。ただし、働き手の不足、魚の不漁（海水温の上昇によるさんま・さけの減少）、風評被害など、震災以外の困難も重なっている。

■ 減災という考え方
巨大な災害の被害を完全に防ぐことは難しい。そこで、被害をできるだけ小さくする減災という考え方が重視されるようになった。
・自助…自分と家族の身を守る。備蓄、避難経路の確認。
・共助…近所や地域で助け合う。避難訓練、要支援者の把握。
・公助…国や自治体による救助・支援。
この三つが組み合わさってはじめて被害を小さくできる。

■ 記憶を伝える工夫
・自然災害伝承碑…過去の災害の状況を刻んだ石碑。2019年に地図記号が新しくつくられ、地形図に表示されるようになった。
・ハザードマップ…浸水が想定される範囲、避難場所、避難経路を示した地図。自治体が作成し配布する。
・震災遺構…被災した建物を保存して伝える。
「ここより下に家を建てるな」と刻まれた明治・昭和の三陸津波の石碑のように、記憶を地図と土地に刻む努力が続けられている。

⚠ 注意：ハザードマップは「安全な場所を示す地図」ではなく「危険が想定される範囲を示す地図」である。想定をこえる災害もあるという前提で使う。`,
