        heading: '三つの農業地域',
        body: `北海道の農業は、地域によってまったく異なる。気候と土の条件がそれを決めている。

■ 石狩平野・上川盆地…稲作
札幌から旭川にかけての内陸は、夏に気温が上がる。泥炭地を客土で改良し、寒さに強い品種（ゆめぴりか、ななつぼしなど）を開発したことで、北海道は米の収穫量が全国第2位となった。かつて「北海道の米はまずい」と言われた時代は過去のものになっている。

■ 十勝平野…畑作
帯広市を中心とする十勝平野は、火山灰土におおわれた広大な平地である。ここでは大型機械を使った大規模な畑作が行われている。
主な作物は、じゃがいも（ばれいしょ）、てんさい（さとうだいこん）、小麦、あずき・いんげんなどの豆類、スイートコーンである。
・てんさい…根から砂糖をとる作物で、寒い地域でも育つ。日本の砂糖の国産原料の大半は北海道のてんさいと沖縄・鹿児島のさとうきびである。
・輪作…同じ作物を毎年同じ畑で作ると、土の特定の養分が減り、病害虫が増える（連作障害）。そこで「じゃがいも→てんさい→豆類→小麦」のように年ごとに作物を変える輪作を行う。豆類は根に共生する菌のはたらきで土に窒素を補う効果もある。

■ 根釧台地…酪農
釧路と根室のあいだに広がる根釧台地は、夏でも海霧（ガス）の影響で気温が上がらず、火山灰土でやせているため、作物の栽培には向かない。しかし牧草はよく育つため、乳牛を飼う酪農が発達した。
・戦後、パイロットファーム（実験農場）が開かれ、その後「新酪農村」の建設によって大規模な酪農経営が広がった。
・牛乳は日持ちしないため、遠い大消費地へ生乳のまま運ぶのは難しい。そこでバター・チーズ・脱脂粉乳などの乳製品に加工して出荷する。北海道の生乳生産量は全国の半分以上を占める。

★ ポイント：「石狩＝米」「十勝＝畑作の輪作」「根釧＝酪農」の三点セットは、北海道の最重要暗記事項である。`,
