        heading: '大規模農業の強みと弱み',
        body: `■ 経営規模のちがい
北海道の農家1戸あたりの耕地面積は約30haで、都府県の平均（約2〜3ha）の10倍以上ある。これは、明治期の開拓で大きな区画に土地が割り当てられたこと、そして初めからアメリカ式の大規模農業を手本にしたことによる。

■ 大規模であることの強み
①大型機械（トラクター、コンバイン、ハーベスター）を使えるので、一人あたりの生産量が大きい。
②生産費を下げられるため、価格の安い外国産と競争しやすい。
③食料自給率が高い（北海道の食料自給率はカロリーベースで200%をこえる）。日本全体の食料供給を支えている。

■ 弱みと課題
①冷害・干ばつ・台風など天候の影響を受けやすい。広い面積が一度に被害を受ける。
②大型機械や施設に多額の投資が必要で、価格が下がると経営が苦しくなる。
③輸入自由化の影響を受けやすい。とくに小麦・乳製品・砂糖は輸入品との競争が激しい。
④働き手の不足と高齢化。広い面積を少人数で管理する必要があり、外国人技能実習生に頼る例も多い。
⑤大消費地から遠く、輸送費と時間がかかる。

■ 新しい取り組み
・スマート農業…GPSで自動操舵するトラクター、ドローンによる生育の把握、搾乳ロボット。広い面積を少ない人手で管理するのに向いている。
・食品加工と六次産業化…生乳をチーズやアイスクリームに、じゃがいもをスナック菓子に加工して付加価値を高める。
・農業体験や観光牧場などのグリーンツーリズム。
・輸出…ホタテや乳製品、菓子などをアジア市場へ。

⚠ 注意：北海道の農業は「大規模だから常に有利」ではない。天候の影響と輸入品との競争という弱点をセットで書けるようにする。`,
