        body: `日本の地形図は、国土交通省の国土地理院が作成・発行している。国土全体を同じ規格でおおう地図であり、災害への備え、道路や施設の計画、学校の学習など、幅広く使われている。

■ 主な縮尺
・2万5千分の1地形図…日本全土をおおう基本図。もっともくわしい地形図で、入試でもこれが中心に出題される。
・5万分の1地形図…より広い範囲を1枚で示す。細かいものは省略される。
・電子国土基本図（地理院地図）…現在はインターネット上で公開され、拡大・縮小や重ね合わせができる。ハザードマップや過去の空中写真も重ねられる。

■ 縮尺とは
縮尺は、実際の距離を地図の上でどれだけ縮めたかを表す割合である。2万5千分の1なら、実際の25,000cmが地図上の1cmになるということである。

★ 大きい縮尺・小さい縮尺
分数として考えると、25000分の1と50000分の1では、25000分の1のほうが値が大きい。したがって2万5千分の1のほうが「縮尺が大きい」という。
・縮尺が大きい（分母が小さい）→ せまい範囲を、くわしく描く。
・縮尺が小さい（分母が大きい）→ 広い範囲を、大まかに描く。
言葉の感覚とは逆になりやすいので注意する。「2万5千分の1のほうが縮尺が小さい」と書くのは誤りである。

■ 同じ範囲を描いたときの紙の大きさ
同じ地域を描くとき、2万5千分の1の地形図は5万分の1の2倍の長さ、面積では4倍の紙が必要になる。長さが2倍なら面積は2×2＝4倍になるからである。

⚠ 注意：「くわしい＝縮尺が小さい」と覚えてしまう受験生が多い。「くわしい＝分母が小さい＝縮尺が大きい」と、分母で判断すると間違えない。`,
