        heading: '逆算と面積の計算',
        body: `■ 実際の距離から地図上の長さを求める
【公式】地図上の長さ ＝ 実際の距離 ÷ 縮尺の分母
このとき、実際の距離を先にcmに直しておくことがポイントである。

■ 例題4：2万5千分の1の地形図で、実際に1.5kmの道は図上何cmか。
1.5km ＝ 1,500m ＝ 150,000cm
150,000cm ÷ 25,000 ＝ 6cm
答え：6cm

■ 例題5：5万分の1の地形図で、実際に3kmの距離は図上何cmか。
3km ＝ 300,000cm
300,000cm ÷ 50,000 ＝ 6cm
答え：6cm
（同じ6cmでも、縮尺がちがえば表す距離がちがう。）

■ 面積の計算
面積は「たて×よこ」なので、長さが縮尺の分母倍になると、面積は分母の2乗倍になる。
2万5千分の1の場合、図上1cmは実際250m。したがって、
図上1cm² ＝ 250m × 250m ＝ 62,500m²
1ha ＝ 10,000m² なので、62,500m² ＝ 6.25ha

■ 例題6：2万5千分の1の地形図で、一辺2cmの正方形の実際の面積は。
一辺：2cm × 25,000 ＝ 50,000cm ＝ 500m
面積：500m × 500m ＝ 250,000m²
1ha＝10,000m² より 250,000 ÷ 10,000 ＝ 25ha
答え：25ha（0.25km²）

■ 例題7：5万分の1の地形図で、図上1cm²は実際何haか。
図上1cm ＝ 500m なので、500m × 500m ＝ 250,000m² ＝ 25ha
答え：25ha
2万5千分の1の6.25haの4倍になっている。長さが2倍なら面積は4倍、という関係の確認になる。

⚠ 注意：面積を求めるとき、長さの計算と同じように「×25,000」を1回だけかけてしまう誤りが多い。面積は2回かける（＝分母の2乗をかける）ことを忘れない。`,
