        heading: '等高線から傾斜を読む',
        body: `■ 間隔と傾斜の関係
等高線が示す高さの差は、同じ地図の中では一定である（2万5千分の1なら常に10m）。したがって、
・線と線の間隔がせまい → 短い水平距離で10m上がる → 傾斜が急。
・線と線の間隔が広い → 長い水平距離をかけて10m上がる → 傾斜がゆるやか。
つまり「混んでいれば急、まばらならゆるやか」である。

■ 傾斜を数値で表す
傾斜は「高さの差 ÷ 水平距離」で表せる。
例）2万5千分の1の地形図で、A地点（標高50m）とB地点（標高150m）が図上4cm離れているとき。
・高さの差：150－50＝100m
・水平距離：4cm×25,000＝100,000cm＝1,000m
・傾斜：100m ÷ 1,000m ＝ 0.1（10分の1、100mにつき10m上がる）

■ 等高線のきまり
①同じ等高線の上は、どこでも標高が同じ。
②等高線は必ず閉じた線になる（地図の外まで続いていて、その図の中では切れているように見えることはある）。
③等高線どうしが交わったり枝分かれしたりすることはない。ただし、垂直に近いがけでは線が重なるため、がけを表す専用の記号（岩がけ・土がけ）が使われる。
④閉じた小さな輪の内側が周囲より高ければ山頂、低ければくぼ地である。くぼ地には内側を指す短い線（ケバ）が付けられる。

■ 標高がわかるその他の表示
・三角点（△）…測量の基準点。山頂などに置かれ、標高が数値で示される。
・水準点…道路沿いなどに置かれ、高さの基準となる。
・標高点…地点の標高を数値で示す点。
これらの数値は、等高線を数えるときの出発点として使う。

⚠ 注意：「等高線の本数が多い＝標高が高い」ではない。本数が多いのは高低差が大きいということであり、間隔がせまければ急斜面という意味になる。`,
