        body: `地形図の問題は、次の順序で見ていけば、初めての土地でも必ず情報を取り出せる。

■ ①縮尺と方位を確認する
まず図の縮尺（2万5千分の1か5万分の1か）を見る。これが決まらないと、距離も面積も等高線の間隔も判断できない。方位は特別な記号がなければ上が北である。

■ ②等高線で地形をつかむ
・線がまばらで標高が低い → 平野・低地。
・線が密 → 山地・急斜面。
・等高線が同心円状に閉じている → 山や丘。
・等高線が山頂側へ食いこむ → 谷（川がある）。
・扇形に等高線が開いている → 扇状地。
・海に向かって等高線がほとんどない広い平地 → 三角州や干拓地の可能性。

■ ③土地利用の記号を見る
田・畑・果樹園・樹林の分布を確認し、②の地形と結びつける。
例）低地に田、台地に畑と住宅、斜面に果樹園と樹林。

■ ④集落と交通を見る
・集落がどこに集まっているか（川ぞい、台地の縁、扇端、道路ぞい）。
・鉄道・道路・駅・インターチェンジの位置。
・役場、学校、病院などの記号は、その集落が中心地であるかどうかを示す。

■ ⑤新旧を比べる（比較問題の場合）
消えたもの（田、桑畑、海岸線、等高線）と増えたもの（建物、道路、鉄道、工場や倉庫の敷地）を書き出す。

■ 数値の確認
問題文が「A—B間の実際の距離」を問うていれば、図上の長さ×縮尺の分母。「面積」なら分母の2乗。「標高差」なら計曲線の数値から等高線を数える。手順を固定しておけば、あわてずにすむ。

★ ポイント：読図の答案は「地形の特徴」→「だからこう利用されている」の順で書く。順序を逆にすると説明が弱くなる。`,
